create table workspace (id bigint generated always as identity primary key, workspace_id uuid not null unique, name varchar(128) not null, code varchar(64) not null unique, status varchar(32) not null default 'active', settings_json jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table app_user (id bigint generated always as identity primary key, user_id uuid not null unique, workspace_id bigint not null references workspace(id), username varchar(128) not null, display_name varchar(128), email varchar(256), role varchar(32) not null default 'member', status varchar(32) not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id, username));
create table task (id bigint generated always as identity primary key, task_id uuid not null unique, workspace_id bigint not null references workspace(id), user_id bigint references app_user(id), title varchar(256), query text not null, route varchar(32) not null, status varchar(32) not null default 'draft', latest_run_id bigint, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table task_run (id bigint generated always as identity primary key, run_id uuid not null unique, task_id bigint not null references task(id), attempt integer not null default 1, status varchar(32) not null, current_node varchar(64), route varchar(32) not null, error_code varchar(32), error_message text, started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(task_id, attempt));
alter table task add constraint fk_task_latest_run foreign key (latest_run_id) references task_run(id);
create table node_run (id bigint generated always as identity primary key, node_run_id uuid not null unique, task_run_id bigint not null references task_run(id) on delete cascade, node_name varchar(128) not null, node_type varchar(32) not null, attempt integer not null default 1, status varchar(32) not null, input_summary text, output_summary text, error_code varchar(32), error_message text, duration_ms bigint, started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(task_run_id,node_name,attempt));
create table conversation_turn (id bigint generated always as identity primary key, turn_id uuid not null unique, task_id bigint references task(id), task_run_id bigint references task_run(id), workspace_id bigint not null references workspace(id), user_id bigint references app_user(id), role varchar(32) not null, content text not null, metadata_json jsonb not null default '{}', created_at timestamptz not null default now());
create table document (id bigint generated always as identity primary key, document_id uuid not null unique, workspace_id bigint not null references workspace(id), uploaded_by bigint references app_user(id), source_file varchar(512) not null, source_type varchar(32) not null, storage_uri varchar(1024), version integer not null default 1, status varchar(32) not null default 'uploaded', quality varchar(32), chunk_count integer not null default 0, checksum varchar(128), error_code varchar(32), error_message text, metadata_json jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table document_chunk (id bigint generated always as identity primary key, chunk_id uuid not null unique, document_id bigint not null references document(id) on delete cascade, parent_chunk_id bigint references document_chunk(id), chunk_role varchar(32) not null, block_type varchar(32) not null, content text not null, location varchar(256), source_anchor varchar(256), confidence numeric(6,5), evidence_type varchar(32), token_count integer, metadata_json jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table index_ref (id bigint generated always as identity primary key, chunk_id bigint not null references document_chunk(id) on delete cascade, index_type varchar(32) not null, provider varchar(64) not null, collection_name varchar(256), external_id varchar(256) not null, index_status varchar(32) not null default 'pending', metadata_json jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(provider,collection_name,external_id));
create table artifact (id bigint generated always as identity primary key, artifact_id uuid not null unique, task_id bigint not null references task(id), task_run_id bigint references task_run(id), artifact_type varchar(32) not null, file_name varchar(512), storage_uri varchar(1024) not null, checksum varchar(128), size_bytes bigint, status varchar(32) not null default 'ready', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(task_id,storage_uri));
create table evidence_ref (id bigint generated always as identity primary key, evidence_id uuid not null unique, task_run_id bigint not null references task_run(id) on delete cascade, document_id bigint references document(id), chunk_id bigint references document_chunk(id), source_file varchar(512), location varchar(256), hash_or_id varchar(256) not null, confidence numeric(6,5), quote text, created_at timestamptz not null default now(), unique(task_run_id,hash_or_id));
create table rag_retrieval_log (id bigint generated always as identity primary key, retrieval_id uuid not null unique, workspace_id bigint references workspace(id), task_run_id bigint references task_run(id), query text not null, top_k integer not null, filters_json jsonb not null default '{}', results_json jsonb not null, duration_ms bigint, created_at timestamptz not null default now());
create table embedding_collection (id bigint generated always as identity primary key, collection_id uuid not null unique, workspace_id bigint not null references workspace(id), name varchar(256) not null, provider varchar(64) not null, model varchar(256) not null, dimension integer not null, metric varchar(32) not null default 'cosine', status varchar(32) not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,name,model));
create table chunk_embedding (id bigint generated always as identity primary key, chunk_id bigint not null references document_chunk(id) on delete cascade, collection_id bigint not null references embedding_collection(id), model varchar(256) not null, dimension integer not null, external_id varchar(256), checksum varchar(128), status varchar(32) not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(chunk_id,collection_id,model));
create index idx_task_workspace_time on task(workspace_id,created_at desc); create index idx_task_run_task_time on task_run(task_id,created_at desc); create index idx_node_run_task on node_run(task_run_id,created_at); create index idx_document_workspace_status on document(workspace_id,status,created_at desc); create index idx_chunk_document_role on document_chunk(document_id,chunk_role); create index idx_chunk_parent on document_chunk(parent_chunk_id); create index idx_artifact_task_time on artifact(task_id,created_at desc); create index idx_evidence_run on evidence_ref(task_run_id,confidence desc); create index idx_retrieval_run on rag_retrieval_log(task_run_id,created_at); create index idx_embedding_collection on chunk_embedding(collection_id,status);
